291.sql:
SELECT COUNT(*) AS answer
FROM molecule
WHERE label = '+';

419.sql:
SELECT COUNT(*) 
FROM cards 
WHERE `borderColor` = 'borderless' AND `edhrecRank` > 12000;

436.sql:
WITH c_rows AS (
    SELECT `id`
    FROM cards
    WHERE `frameEffects` = 'extendedart'
)
SELECT COUNT(*) AS answer FROM c_rows;
SELECT `id` FROM c_rows;

591.sql:
SELECT COUNT(DISTINCT `UserId`) AS answer
FROM badges
WHERE `Name` = 'Supporter' AND STRFTIME('%Y', `Date`) = '2011';

625.sql:
SELECT COUNT(*) AS answer
FROM users
WHERE `Location` LIKE '%New York%';

864.sql:
SELECT COUNT(*) AS answer
FROM results
WHERE raceId = 945 AND time IS NOT NULL;
